create extension if not exists pgcrypto;
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,username text unique not null,role text not null default 'admin',active boolean not null default true);
create table if not exists public.question_sets(id uuid primary key default gen_random_uuid(),title text not null,description text,status text not null default 'draft' check(status in('draft','published','archived')),created_at timestamptz default now());
create table if not exists public.questions(id uuid primary key default gen_random_uuid(),set_id uuid not null references public.question_sets(id) on delete cascade,body text not null,explanation text not null default '',law_name text default '',article_number text default '',source_url text default '',position int not null default 1);
create table if not exists public.options(id uuid primary key default gen_random_uuid(),question_id uuid not null references public.questions(id) on delete cascade,label text not null,is_correct boolean not null default false,position int not null default 1);
create table if not exists public.participations(id uuid primary key default gen_random_uuid(),set_id uuid not null references public.question_sets(id),full_name text not null,phone_hash text not null,score int not null,total int not null,completed_at timestamptz default now());
create table if not exists public.participation_answers(id uuid primary key default gen_random_uuid(),participation_id uuid not null references public.participations(id) on delete cascade,question_id uuid not null references public.questions(id),option_id uuid not null references public.options(id),is_correct boolean not null);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid() and active); $$;
alter table public.admin_users enable row level security;alter table public.question_sets enable row level security;alter table public.questions enable row level security;alter table public.options enable row level security;alter table public.participations enable row level security;alter table public.participation_answers enable row level security;
create policy "admin users access" on public.admin_users for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "published sets public" on public.question_sets for select to anon,authenticated using(status='published' or public.is_admin());
create policy "admin sets manage" on public.question_sets for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "published questions public" on public.questions for select to anon,authenticated using(exists(select 1 from public.question_sets s where s.id=set_id and s.status='published') or public.is_admin());
create policy "admin questions manage" on public.questions for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "published options public" on public.options for select to anon,authenticated using(exists(select 1 from public.questions q join public.question_sets s on s.id=q.set_id where q.id=question_id and s.status='published') or public.is_admin());
create policy "admin options manage" on public.options for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "admins read participants" on public.participations for select to authenticated using(public.is_admin());
create policy "admins read answers" on public.participation_answers for select to authenticated using(public.is_admin());
create or replace view public.weekly_leaderboard with(security_invoker=true) as select left(full_name,1)||'•••' display_name,score,completed_at from public.participations where completed_at>=date_trunc('week',now()) order by score desc,completed_at asc limit 10;
grant select on public.question_sets,public.questions,public.options,public.weekly_leaderboard to anon,authenticated;
